sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {
        // Ensure we only act when status changes
        if (!previous || current.reservation_status == previous.reservation_status) {
            return;
        }

        var wsGR = new GlideRecord('x_787189_wrm_workspace_options'); // Update with actual table name

        // Assuming there is a reference field linking Reservation to Workspace
        if (current.workspace && wsGR.get(current.workspace)) {

            // Normalize status value (adjust values to your exact choice values)

            var reservationStatus = current.reservation_status + '';


            if (reservationStatus == 'pending_check_in' || reservationStatus == 'checked_in') {
                wsGR.status = 'unavailable';
            } else if (reservationStatus == 'checked_out') {
                wsGR.status = 'available';
            } else if (reservationStatus == 'no_show' || resevationStatus == 'cancelled') {
                wsGR.status = 'available';
            }

            wsGR.update();
        }

    } catch (ex) {

        gs.error('Workspace Options Sync BR Error: ' + ex.message);
    }

})(current, previous);
